style.css:
@-moz-document domain("youtube.com") {
/* Liquid Glass for YouTube | YouTube desktop */
  html {
    --lg-base: #e9edf9;
    --lg-aurora: rgba(132, 172, 239, 0.549);
    --lg-orchid: rgba(196, 166, 240, 0.639);
    --lg-tide: rgba(124, 221, 210, 0.522);
    --lg-glass: rgba(244, 247, 255, 0.878);
    --lg-panel: rgba(255, 255, 255, 0.502);
    --lg-shine: rgba(255, 255, 255, 0.710);
    --lg-edge: rgba(104, 124, 161, 0.231);
    --lg-shadow: rgba(39, 61, 104, 0.145);
    --lg-ink: #151e39;
    --lg-muted: #49536b;
    --lg-focus: #485cdb;
    --lg-gradient: linear-gradient(105deg, #8deceb, #a6acff 48%, #efb1fa);
    --lg-surface: linear-gradient(145deg, var(--lg-shine), transparent 53%), var(--lg-panel);
    --lg-depth: inset 0 1px 0 var(--lg-shine), 0 6px 20px var(--lg-shadow);
  }

  html[dark] {
    --lg-base: #0c1022;
    --lg-aurora: rgba(57, 86, 168, 0.459);
    --lg-orchid: rgba(117, 57, 150, 0.396);
    --lg-tide: rgba(24, 118, 123, 0.349);
    --lg-glass: rgba(20, 26, 50, 0.863);
    --lg-panel: rgba(154, 171, 245, 0.106);
    --lg-shine: rgba(214, 224, 255, 0.133);
    --lg-edge: rgba(192, 203, 255, 0.208);
    --lg-shadow: rgba(3, 5, 16, 0.333);
    --lg-ink: #f5f5ff;
    --lg-muted: #b8c2df;
    --lg-focus: #b3b8ff;
  }

  /* Aurora behind the feed, channel pages and watch page. */
  ytd-app {
    --yt-spec-base-background: var(--lg-base) !important;
    --yt-spec-raised-background: var(--lg-glass) !important;
    --yt-spec-menu-background: var(--lg-glass) !important;
    --yt-spec-badge-chip-background: var(--lg-panel) !important;
    --yt-spec-10-percent-layer: var(--lg-edge) !important;
    --yt-spec-text-primary: var(--lg-ink) !important;
    --yt-spec-text-secondary: var(--lg-muted) !important;
    background:
      radial-gradient(ellipse at 12% 7%, var(--lg-aurora), transparent 54%),
      radial-gradient(ellipse at 96% 12%, var(--lg-orchid), transparent 49%),
      radial-gradient(ellipse at 70% 98%, var(--lg-tide), transparent 55%),
      var(--lg-base) !important;
    background-attachment: fixed !important;
  }

  ytd-app ytd-browse,
  ytd-app ytd-search,
  ytd-app ytd-watch-flexy,
  ytd-app ytd-rich-grid-renderer,
  ytd-app ytd-mini-guide-renderer,
  ytd-app ytd-guide-renderer,
  ytd-app #guide-content.ytd-app {
    background-color: transparent !important;
  }

  /* Frosted navigation and menus. */
  ytd-masthead,
  ytd-feed-filter-chip-bar-renderer #chips-wrapper,
  ytd-popup-container tp-yt-paper-listbox,
  ytd-popup-container ytd-multi-page-menu-renderer {
    background: linear-gradient(115deg, var(--lg-shine), transparent 65%), var(--lg-glass) !important;
    backdrop-filter: blur(18px) saturate(150%);
    box-shadow: inset 0 -1px 0 var(--lg-edge), 0 8px 24px var(--lg-shadow);
  }

  ytd-popup-container tp-yt-paper-listbox,
  ytd-popup-container ytd-multi-page-menu-renderer {
    border-radius: 16px !important;
  }

  ytd-masthead #search-form,
  ytd-masthead .ytSearchboxComponentInputBox,
  ytd-masthead .ytSearchboxComponentSearchButton,
  ytd-searchbox #container,
  ytd-searchbox #search-icon-legacy {
    background: var(--lg-surface) !important;
    border-color: var(--lg-edge) !important;
    box-shadow: inset 0 1px 0 var(--lg-shine);
  }

  ytd-masthead #end .yt-spec-button-shape-next--tonal {
    border: 1px solid var(--lg-edge);
  }

  /* Glossy chips, buttons, and selected navigation. */
  ytd-app yt-chip-cloud-chip-renderer #chip,
  ytd-app yt-chip-cloud-chip-renderer,
  ytd-app .yt-spec-button-shape-next--tonal,
  ytd-app #description.ytd-watch-metadata {
    background: var(--lg-surface) !important;
    box-shadow: inset 0 0 0 1px var(--lg-edge), inset 0 1px 0 var(--lg-shine);
  }

  ytd-app yt-chip-cloud-chip-renderer {
    border-radius: 11px !important;
  }

  ytd-app yt-chip-cloud-chip-renderer #chip {
    background: transparent !important;
    box-shadow: none;
  }

  ytd-app yt-chip-cloud-chip-renderer[selected],
  ytd-app yt-chip-cloud-chip-renderer[aria-selected="true"] {
    background: var(--lg-gradient) !important;
    color: #111731 !important;
  }

  ytd-app yt-chip-cloud-chip-renderer[selected] #text,
  ytd-app yt-chip-cloud-chip-renderer[aria-selected="true"] #text {
    color: #111731 !important;
  }

  ytd-app ytd-guide-entry-renderer[active] > a,
  ytd-app ytd-mini-guide-entry-renderer[active] > a {
    background: var(--lg-surface) !important;
    box-shadow: inset 0 0 0 1px var(--lg-edge);
    border-radius: 12px;
  }

  /* Lens-like thumbnail frames and a sheen on hover. */
  ytd-app ytd-thumbnail #thumbnail,
  ytd-app yt-thumbnail-view-model .yt-thumbnail-view-model__image {
    border-radius: 17px !important;
    box-shadow: 0 7px 19px var(--lg-shadow);
  }

  ytd-app ytd-rich-item-renderer ytd-thumbnail,
  ytd-app ytd-rich-item-renderer yt-thumbnail-view-model,
  ytd-app ytd-video-renderer ytd-thumbnail,
  ytd-app ytd-video-renderer yt-thumbnail-view-model {
    border-radius: 17px !important;
    outline: 1px solid var(--lg-edge);
    outline-offset: -1px;
    transition: box-shadow 180ms ease, outline-color 180ms ease;
  }

  ytd-app ytd-rich-item-renderer:hover ytd-thumbnail,
  ytd-app ytd-rich-item-renderer:hover yt-thumbnail-view-model,
  ytd-app ytd-video-renderer:hover ytd-thumbnail,
  ytd-app ytd-video-renderer:hover yt-thumbnail-view-model {
    outline-color: var(--lg-focus);
    box-shadow: var(--lg-depth), 0 0 22px var(--lg-aurora);
  }

  /* Watch-page glass and a pearlescent player timeline. */
  ytd-watch-metadata #description {
    border-radius: 17px !important;
  }

  ytd-app .ytp-play-progress,
  ytd-app .ytp-swatch-background-color {
    background: var(--lg-gradient) !important;
  }

  ytd-app .ytp-scrubber-button {
    background: #e7dbff !important;
    box-shadow: 0 0 9px rgba(178, 190, 255, 0.722);
  }

  /* Clear keyboard focus, plus reduced-motion and high-contrast support. */
  ytd-app a:focus-visible,
  ytd-app button:focus-visible,
  ytd-app [role="button"]:focus-visible,
  ytd-app input:focus-visible {
    outline: 2px solid var(--lg-focus) !important;
    outline-offset: 2px;
  }

  @media (prefers-reduced-motion: reduce) {
    ytd-app ytd-thumbnail,
    ytd-app yt-thumbnail-view-model {
      transition: none !important;
    }
  }

  @media (forced-colors: active) {
    ytd-app,
    ytd-masthead,
    ytd-feed-filter-chip-bar-renderer #chips-wrapper {
      background: Canvas !important;
    }

    ytd-app a:focus-visible,
    ytd-app button:focus-visible,
    ytd-app [role="button"]:focus-visible,
    ytd-app input:focus-visible {
      outline-color: Highlight !important;
    }
  }
}
